import React from "react";
import { Text, View } from "react-native";
import { SkeuoCard } from "../skeuo-card";
import { useSkeuo } from "../theme";
export function SummaryCard({
  label = "Total balance",
  value = "₹42,860",
  detail = "+8.2% this month",
}: {
  label?: string;
  value?: string;
  detail?: string;
}) {
  const { colors: c } = useSkeuo();
  return (
    <SkeuoCard style={{ padding: 22, gap: 14 }}>
      <View style={{ flexDirection: "row", justifyContent: "space-between" }}>
        <Text style={{ color: c.muted, fontSize: 13 }}>{label}</Text>
        <View
          style={{
            width: 7,
            height: 7,
            borderRadius: 4,
            backgroundColor: c.accent,
            marginTop: 5,
          }}
        />
      </View>
      <Text
        style={{
          fontSize: 42,
          fontWeight: "300",
          letterSpacing: -2,
          color: c.ink,
          fontVariant: ["tabular-nums"],
        }}
      >
        {value}
      </Text>
      <View
        style={{ borderTopWidth: 1, borderTopColor: c.edge, paddingTop: 12 }}
      >
        <Text style={{ color: c.accent, fontSize: 12 }}>{detail}</Text>
      </View>
    </SkeuoCard>
  );
}

import { View, ViewProps } from "react-native";
import { useSkeuo } from "./theme";
import { styles } from "./styles";
export function SkeuoCard({ style, ...props }: ViewProps) {
  const { colors } = useSkeuo();
  return (
    <View
      {...props}
      style={[
        styles.card,
        { backgroundColor: colors.surface, borderColor: colors.edge },
        style,
      ]}
    />
  );
}

import React, { createContext, useContext } from "react";
import { useColorScheme } from "nativewind";
import * as Haptics from "expo-haptics";

export const themes = {
  light: {
    background: "#ffffff",
    surface: "#f5f5f2",
    raised: "#fafaf8",
    well: "#e9e9e5",
    edge: "#d1d1cb",
    base: "#d9d9d3",
    ink: "#202020",
    muted: "#686863",
    accent: "#365e50",
    accentInk: "#ffffff",
  },
  dark: {
    background: "#000000",
    surface: "#191919",
    raised: "#252525",
    well: "#111111",
    edge: "#3b3b39",
    base: "#080808",
    ink: "#efefeb",
    muted: "#aaaAA5",
    accent: "#9ab5a6",
    accentInk: "#14251c",
  },
};
type ThemeState = { colors: typeof themes.light; dark: boolean; haptics: boolean; onSound?: () => void };
const Context = createContext<ThemeState | null>(null);
export function SkeuoProvider({
  children,
  appearance = "system",
  haptics = false,
  onSound,
  colors: overrides,
}: {
  children: React.ReactNode;
  appearance?: "light" | "dark" | "system";
  haptics?: boolean;
  onSound?: () => void;
  colors?: Partial<typeof themes.light>;
}) {
  const { colorScheme: system } = useColorScheme();
  const dark = (appearance === "system" ? system : appearance) === "dark";
  return (
    <Context.Provider
      value={{
        colors: { ...(dark ? themes.dark : themes.light), ...overrides },
        dark,
        haptics,
        onSound,
      }}
    >
      {children}
    </Context.Provider>
  );
}
export function useSkeuo(): ThemeState {
  const context = useContext(Context);
  const { colorScheme } = useColorScheme();
  return context ?? { colors: colorScheme === "dark" ? themes.dark : themes.light, dark: colorScheme === "dark", haptics: false };
}
export function useFeedback() {
  const { haptics, onSound } = useSkeuo();
  return () => {
    onSound?.();
    if (haptics) void Haptics.selectionAsync().catch(() => {});
  };
}
